// Server-side bot check — never trust the client-side honeypot/timing alone,
// since a bot can skip the browser entirely and POST straight to this webhook.
const body = $input.first().json.body || {};

const honeypotFilled = !!(body.website && String(body.website).trim());
const elapsedMs = Number(body.elapsedMs || 0);
const tooFast = elapsedMs < 3000;

const isBot = honeypotFilled || tooFast;

// This form is a sales inquiry (services checklist), so every real submission
// goes to Sales. Fill in the real address + Teams webhook before going live.
const SALES_EMAIL = 'sales@openmind.in';
const SALES_TEAMS_WEBHOOK_URL = 'TODO_SALES_TEAMS_WEBHOOK_URL';

const requirements = Array.isArray(body.requirements) ? body.requirements.join(', ') : (body.requirements || '');

return [{
  json: {
    isBot,
    name: body.name || '',
    email: body.email || '',
    phone: `${body.countryCode || ''} ${body.phone || ''}`.trim(),
    companyName: body.companyName || '',
    companyWebsite: body.companyWebsite || '',
    requirements,
    comments: body.comments || '',
    toEmail: SALES_EMAIL,
    teamsWebhookUrl: SALES_TEAMS_WEBHOOK_URL,
  },
}];

